		var pBoardInfo = WebSquare.net.getParameter( "boardInfo" );  // 게시판정보
     	var pStatementId = WebSquare.net.getParameter( "statementId" );	//글번호
		var pBoardTyp = WebSquare.net.getParameter( "boardTyp" );	//게시판유형

		var PAGE_CNT = WebSquare.net.getParameter( "PAGE_CNT" );

		var saveGb = WebSquare.net.getParameter( "saveGb" );

      /**************************************************************************
		* function    : init
		* Description : 
		* Parameter   : null
		* Return      : null
		**************************************************************************/	
		function init() {
			this.document.title=divisionNm;
			resizeIframe();

			if(saveGb == "U" || saveGb == "R") searchData();
			genCaptcha();
		}


		/**************************************************************************
		 * function    : searchData
		 * Description : 게시판 조회
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/	
		function searchData() {
			WebSquare.ModelUtil.removeChildNodes( "BISComBoardDTO" );

        	BISComBoardDTO =  {"BISComBoardDTO":{}};

        	setValue("BISComBoardDTO/boardID", pBoardInfo);
        	setValue("BISComBoardDTO/boardTyp", pBoardTyp);
        	setValue("BISComBoardDTO/statementId", pStatementId);
        	/*
        	pfm_insertValue(BISComBoardDTO,"boardID", pBoardInfo);
        	pfm_insertValue(BISComBoardDTO,"boardTyp", pBoardTyp);
			pfm_insertValue(BISComBoardDTO,"statementId", pStatementId);
	      */
        	callProFrameSync("BIS-COM","BISComBoardSO","selectDetail2",BISComBoardDTO, "BISComBoardDTO","resp");
		}

		/**************************************************************************
       * function    : getFileName
       * Description : 파일 정보에서 Array 리턴
       * Parameter   : index, str
       * Return      : null
       **************************************************************************/
      function getFileName(index, str) {
      	if (str == undefined || str == "") return;

			if (str.indexOf("^") > 0) {
			    var arr = str.split("^");
			    if (arr[index] != undefined && arr.length > 0 && arr.length >= index) {
					return arr[index].split("|");
			    }
			} else {
				if (index > 0) return;
				return str.split("|");
			}
      }


		/**************************************************************************
		 * function    : fileDownloadView
		 * Description : 파일 다운로드
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
		function fileDownloadView(obj) {
			var str1 = eval("generatorFileList_"+obj.getID().split("_")[1]+"_ATTR_NM").getValue();
			var str2 = eval("generatorFileList_"+obj.getID().split("_")[1]+"_ATTACH_SAVE_FILEPATH").getValue();
			var str3 = eval("generatorFileList_"+obj.getID().split("_")[1]+"_ATTACH_FILENM").getValue();
			var str4 = eval("generatorFileList_"+obj.getID().split("_")[1]+"_ORIGINAL_FILENAME").getValue();
			comFileDownload(str1,str2,str3,str4);
		}      	


     	/**************************************************************************
      * function    : callBack
      * Description : submission 실행 후 Callback
      * Parameter   : retAction(submission 실행 Action), rowCount(조회 목록 총 건수)
      * Return      : null
      **************************************************************************/
     	function callBack(svcId,fnId,strResp) {   
     		if (svcId == "BISComBoardSO") {
     			if (fnId == "selectDetail2") {

     				/*
     				var DETAIL_FILE_NM = getValue("resp/root/message/BISComBoardDTO/attachFile");

     				for(var i=0; i<DETAIL_FILE_NM.split("^").length; i++){
     					generatorFileList.insert();
     				}

     				for(var a=0; a<DETAIL_FILE_NM.split("^").length; a++){
     					var str = DETAIL_FILE_NM.split("^")[a];

     					var arrData = getFileName(a, str);
						generatorFileList.getChild(a, "ATTACH_FILESEQ").setValue( arrData[0] );
						generatorFileList.getChild(a, "ATTR_NM").setValue( arrData[1] );
						generatorFileList.getChild(a, "ATTACH_SAVE_FILEPATH").setValue( arrData[2] );
						generatorFileList.getChild(a, "ATTACH_FILENM").setValue( arrData[3] );
						generatorFileList.getChild(a, "ORIGINAL_FILENAME").setValue( arrData[4] );
						generatorFileList.getChild(a, "imgAttachFile").setTitle( arrData[4] );

					}
					*/

					if (pBoardTyp == "QNA" && saveGb == "R") {
						str = "Re:";
						write_title.setValue( str+getValue("resp/root/message/BISComBoardDTO/title") );
						//write_registOrg.setValue( getValue("resp/root/message/BISComBoardDTO/registOrg") );
						str = "\r\n\r\n\r\n\r\n---------------------------------------------------------------\r\n";
						write_content.setValue( str+getValue("resp/root/message/BISComBoardDTO/content").replaceAll("</br>","\n") );
					} else {
						write_title.setValue( getValue("resp/root/message/BISComBoardDTO/title") );
     					write_content.setValue( getValue("resp/root/message/BISComBoardDTO/content").replaceAll("</br>","\n") );
     					write_registOrg.setValue( getValue("resp/root/message/BISComBoardDTO/registOrg") );
     					write_password.setValue( getValue("resp/root/message/BISComBoardDTO/password") );
					}					
					resizeIframe();	
     			}else if (fnId == "saveBISBoard") {
     				PAGE_CNT = 1;
     				showMain();
     			}
     			resizeIframe();

     		}
		}


		/**************************************************************************
		* function    : saveBeforeCheck
		* Description : 저장 전 확인
		* Parameter   : null
		* Return      : null
		**************************************************************************/	
		function saveBeforeCheck() {

			if(write_registOrg.getValue() == ""){
				var msg = "작성자를 입력하세요.";
				showMsgString(msg);
				write_registOrg.focus();
				return;
			}

			if(write_password.getValue() == ""){
				var msg = "비밀번호를 입력하세요.";
				showMsgString(msg);
				write_password.focus();
				return;
			}else if(write_password.getValue().length < 8){
				var msg = "비밀번호는 8자 이상 입력해야 합니다.";
				showMsgString(msg);
				write_password.focus();
				return;
			}

			if(write_title.getValue() == ""){
				var msg = "제목을 입력하세요.";
				showMsgString(msg);
				write_title.focus();
				return;
			}

			if(write_content.getValue() == ""){
				var msg = "내용을 입력하세요.";
				showMsgString(msg);
				write_content.focus();
				return;
			}else if(write_content.getValue().length > 4000){
				var msg = "4000자 이상 입력할 수 없습니다.";
				showMsgString(msg);
				write_content.focus();
				return;
			}

			if(write_content.getValue().indexOf("iframe") >= 0 || write_content.getValue().indexOf("script") >= 0 ){ 
				var msg = "iframe, script 는 사용하실 수 없습니다.";
				showMsgString(msg);
				write_content.focus();
				return;
			}	


			showConfirm("", "saveData()", "저장 하시겠습니까?");
		}


		/**************************************************************************
		* function    : saveData
		* Description : 저장 전 확인
		* Parameter   : null
		* Return      : null
		**************************************************************************/	
		function saveData() {
			WebSquare.ModelUtil.removeChildNodes( "reqCud" );

		   setValue("reqCud/BISComBoardDTO/boardID", pBoardInfo );
		   if(pStatementId != ""){
		   	setValue("reqCud/BISComBoardDTO/statementId", pStatementId );
		   }	

		   if(saveGb == "R"){ 
		   	saveGb = "C";
		   	setValue("reqCud/BISComBoardDTO/parentStatementId", pStatementId);
		   	setValue("reqCud/BISComBoardDTO/statementStp", WebSquare.util.parseInt( getValue("resp/root/message/BISComBoardDTO/statementStp"), 1)+1);
		   }

		   setValue("reqCud/BISComBoardDTO/val100", saveGb ); 
			setValue("reqCud/BISComBoardDTO/registOrg", write_registOrg.getValue() );
			setValue("reqCud/BISComBoardDTO/writerNm", write_registOrg.getValue() );
			setValue("reqCud/BISComBoardDTO/registUser", write_registOrg.getValue() );
	    	setValue("reqCud/BISComBoardDTO/password", write_password.getValue() );
	    	setValue("reqCud/BISComBoardDTO/title", write_title.getValue() );
	    	setValue("reqCud/BISComBoardDTO/content", write_content.getValue() );



        	//var BISComBoardDTO =  {"BISComBoardDTO":{}};
        	//callProFrameSync("BIS-COM","BISComBoardSO","saveBISBoard",BISComBoardDTO, "reqCud/BISComBoardDTO","respCud");

        	var BISComBoardDTO = WebSquare.xml.indent(getInstanceNode("reqCud/BISComBoardDTO"));
        	callProFrameAdvanced("BIS-COM","BISComBoardSO","saveBISBoard",BISComBoardDTO,"reqCud", false);

		}	


	  /**************************************************************************
       * function    : showMain
       * Description : 목록으로 이동
       * Parameter   : null
       * Return      : null
       **************************************************************************/
      function showMain() {
      	if(saveGb=="C") PAGE_CNT = 1;
      	parent.maincontent.setSrc("/xml/board/BISItgtBoardList" + pBoardTyp + ".xml"
      										+ "&PAGE_CNT=" + PAGE_CNT
      										+ "&boardInfo=" + pBoardInfo + "&boardTyp=" + pBoardTyp
      										+ "&divisionId=" + divisionId + "&topMenuIndex=" + topMenuIndex
      										);
      }

	  /**************************************************************************
       * function    : genCaptcha
       * Description : 목록으로 이동
       * Parameter   : null
       * Return      : null
       **************************************************************************/
		function genCaptcha(){
		 	imgCaptcha.setSrc( "/genCaptcha.jsp?id="+Math.random() );
		 	inputCaptcha.setValue( "" );
		}

	  /**************************************************************************
       * function    : showMain
       * Description : 목록으로 이동
       * Parameter   : null
       * Return      : null
       **************************************************************************/		         
		function validCaptcha(){
				var sendOpt = {};

				sendOpt.action = "/validCaptcha.jsp";
				sendOpt.mode = "synchronous";
				sendOpt.mediatype = "application/x-www-form-urlencoded";
				sendOpt.method = "post"; 
				sendOpt.requestData = "answer="+inputCaptcha.getValue();
				sendOpt.requestHeader = {insUserData:"test"};
				sendOpt.success = function (e){
					if(e.responseText == "true") {
						saveBeforeCheck();
						clearCaptcha();
					} else {
						showMsgString("올바른 보안문자를 입력해주세요.");
						inputCaptcha.focus();
					}
				};

				sendOpt.error = function (e){
					showMsgString("보안문자 검증이 실패했습니다.");
	        	};

        		WebSquare.net.ajax( sendOpt );				
		}


	  /**************************************************************************
       * function    : showMain
       * Description : 목록으로 이동
       * Parameter   : null
       * Return      : null
       **************************************************************************/		         
		function clearCaptcha(){
				var sendOpt = {};

				sendOpt.action = "/clearCaptcha.jsp";
				sendOpt.mode = "synchronous";
				sendOpt.mediatype = "application/x-www-form-urlencoded";
				sendOpt.method = "post"; 


        		WebSquare.net.ajax(  );				
		}

